/**
* Maps any model ID or name to its signature gradient theme.
*/
function getModelGradientTheme(modelIdOrName) {
	const raw = String(modelIdOrName || "").toLowerCase().trim();
	if (raw.includes("deepseek")) return MODEL_GRADIENT_THEMES.deepseek;
	if (raw.includes("glm")) return MODEL_GRADIENT_THEMES.glm;
	if (raw.includes("qwen")) return MODEL_GRADIENT_THEMES.qwen;
	if (raw.includes("claude") || raw.includes("sonnet") || raw.includes("opus")) return MODEL_GRADIENT_THEMES.claude;
	if (raw.includes("gpt") || raw.includes("luna") || raw.includes("sol") || raw.includes("astra") || raw.includes("o3") || raw.includes("o4")) return MODEL_GRADIENT_THEMES.gpt;
	if (raw.includes("grok") || raw.includes("uncensored") || raw.includes("limitless")) return MODEL_GRADIENT_THEMES.grok;
	if (raw.includes("gemini") || raw.includes("argon") || raw.includes("gemma")) return MODEL_GRADIENT_THEMES.gemini;
	if (raw.includes("kimi") || raw.includes("mimo") || raw.includes("minimax") || raw.includes("muse") || raw.includes("agnes") || raw.includes("ernie") || raw.includes("minicpm") || raw.includes("hy3") || raw.includes("hy4")) return MODEL_GRADIENT_THEMES.kimi;
	if (raw.includes("atria") || raw.includes("agents") || raw.includes("llama") || raw.includes("mistral") || raw.includes("nemotron") || raw.includes("laguna") || raw.includes("flint")) return MODEL_GRADIENT_THEMES.atria;
	if (raw.includes("auto") || raw.includes("flm")) return MODEL_GRADIENT_THEMES.auto;
	return EXACT_SUNSET_ORANGE_THEME;
}
function getStoredBackgroundGradientMode() {
	if (typeof window === "undefined") return "dynamic-model";
	try {
		const val = localStorage.getItem("kinich_bg_gradient_mode");
		if (val === "exact-sunset" || val === "subtle" || val === "off") return val;
	} catch {}
	return "dynamic-model";
}
function setStoredBackgroundGradientMode(mode) {
	if (typeof window === "undefined") return;
	try {
		localStorage.setItem("kinich_bg_gradient_mode", mode);
	} catch {}
}
