function formatFileSize(bytes) {
	if (!bytes || bytes <= 0) return "0 B";
	if (bytes < 1024) return `${bytes} B`;
	if (bytes < 1048576) return `${(bytes / 1024).toFixed(1)} KB`;
	return `${(bytes / 1048576).toFixed(1)} MB`;
}
function getFileCategory(name, type) {
	const ext = name.split(".").pop()?.toLowerCase() || "";
	if (type.startsWith("image/") || [
		"png",
		"jpg",
		"jpeg",
		"webp",
		"gif",
		"svg",
		"bmp",
		"ico",
		"tiff"
	].includes(ext)) return {
		category: "image",
		color: "text-blue-500"
	};
	if (type.includes("pdf") || ext === "pdf") return {
		category: "pdf",
		color: "text-red-500"
	};
	if (type.startsWith("audio/") || [
		"mp3",
		"wav",
		"ogg",
		"m4a",
		"aac",
		"flac",
		"opus",
		"wma"
	].includes(ext)) return {
		category: "audio",
		color: "text-amber-500"
	};
	if (type.startsWith("video/") || [
		"mp4",
		"webm",
		"mov",
		"mkv",
		"avi",
		"m4v",
		"flv"
	].includes(ext)) return {
		category: "video",
		color: "text-purple-500"
	};
	if ([
		"json",
		"csv",
		"tsv",
		"xlsx",
		"xls",
		"parquet"
	].includes(ext) || type.includes("csv") || type.includes("json")) return {
		category: "data",
		color: "text-emerald-500"
	};
	if ([
		"js",
		"jsx",
		"ts",
		"tsx",
		"py",
		"java",
		"c",
		"cpp",
		"h",
		"hpp",
		"cs",
		"go",
		"rs",
		"php",
		"rb",
		"swift",
		"kt",
		"sql",
		"html",
		"css",
		"scss",
		"xml",
		"yaml",
		"yml",
		"sh",
		"bash",
		"env",
		"toml",
		"ini",
		"dockerfile",
		"vue",
		"svelte",
		"r",
		"m"
	].includes(ext)) return {
		category: "code",
		color: "text-cyan-500"
	};
	if ([
		"doc",
		"docx",
		"txt",
		"md",
		"rtf",
		"odt",
		"tex",
		"log"
	].includes(ext)) return {
		category: "document",
		color: "text-indigo-500"
	};
	return {
		category: "other",
		color: "text-neutral-400"
	};
}
