function extractAgentMapFromContext(query, content) {
	`${query} ${content}`.trim();
	const isSpatialQuery = /\b(map|route|itinerary|travel|places to visit|cities|landmarks|neighborhoods|where is|locations in|trip to|guide to|coordinates|latitude|longitude)\b/i.test(query) || /\b(itinerary|day 1|day 2|landmarks|destinations|coordinates|neighborhoods)\b/i.test(content.slice(0, 800));
	const isWorkflowQuery = /\b(agent workflow|pipeline architecture|execution graph|multi-agent|orchestration|roadmap steps)\b/i.test(query);
	if (!isSpatialQuery && !isWorkflowQuery) return null;
	const lines = content.replace(/<think>[\s\S]*?(?:<\/think>|$)/gi, "").replace(/```[\s\S]*?```/g, "").split("\n").map((l) => l.trim()).filter(Boolean);
	const extractedItems = [];
	for (let i = 0; i < lines.length; i++) {
		const l = lines[i];
		const headingMatch = l.match(/^#{2,4}\s+(.+)$/);
		const boldBulletMatch = l.match(/^[-*•\d.]+\s+\*\*(.+?)\*\*[:\s-]*(.*)$/);
		if (headingMatch) {
			const h = headingMatch[1].replace(/[*_`]/g, "").replace(/\[\d+\](\(#cite-\d+\))?/g, "").trim();
			if (h.length > 2 && h.length < 55 && !/^(summary|conclusion|overview|references|sources)/i.test(h)) {
				const nextLine = (lines[i + 1] || "").replace(/\[\d+\](\(#cite-\d+\))?/g, "").replace(/[*_`#]/g, "").trim();
				extractedItems.push({
					title: h,
					desc: nextLine.slice(0, 140)
				});
			}
		} else if (boldBulletMatch) {
			const bTitle = boldBulletMatch[1].replace(/[*_`]/g, "").trim();
			const bDesc = boldBulletMatch[2].replace(/\[\d+\](\(#cite-\d+\))?/g, "").replace(/[*_`]/g, "").trim();
			if (bTitle.length > 2 && bTitle.length < 55) extractedItems.push({
				title: bTitle,
				desc: bDesc.slice(0, 140)
			});
		}
		if (extractedItems.length >= 5) break;
	}
	if (extractedItems.length < 2) return null;
	const positions = [
		{
			x: 20,
			y: 30
		},
		{
			x: 48,
			y: 24
		},
		{
			x: 76,
			y: 38
		},
		{
			x: 34,
			y: 68
		},
		{
			x: 66,
			y: 72
		}
	];
	const nodes = extractedItems.slice(0, 5).map((item, idx) => ({
		id: `node-${idx + 1}`,
		label: item.title,
		subtitle: isSpatialQuery ? `Stop #${idx + 1}` : `Stage ${idx + 1}`,
		description: item.desc || `Key ${isSpatialQuery ? "location" : "node"} in "${query || "analysis"}".`,
		status: "completed",
		x: positions[idx % positions.length].x,
		y: positions[idx % positions.length].y
	}));
	return {
		title: isSpatialQuery ? "Interactive Spatial & Location Map" : "Agent Execution Topology Map",
		subtitle: query ? `Mapped ${nodes.length} nodes for "${query}"` : `${nodes.length} active nodes`,
		mode: isSpatialQuery ? "spatial" : "workflow",
		nodes
	};
}
