/**
* Captures and validates an inbound referral code from the URL on landing.
* Saves to both localStorage and a 30-day cookie to survive OAuth redirects.
* Strictly ignores and clears self-referral or invalid links.
*/
async function captureInboundReferral() {
	const code = extractReferralCodeFromUrl();
	const isDeepLinkPath = typeof window !== "undefined" && /^\/(?:r|invite)\//i.test(window.location.pathname);
	if (code) {
		if (isSelfReferralCode(code)) {
			clearPendingReferral();
			if (isDeepLinkPath) try {
				window.history.replaceState({}, "", "/");
			} catch {}
			return null;
		}
		const pending = {
			code,
			capturedAt: Date.now()
		};
		try {
			localStorage.setItem(STORAGE_KEY, JSON.stringify(pending));
		} catch {}
		setCookie(COOKIE_NAME, code, COOKIE_MAX_AGE);
		try {
			const res = await apiFetch(`/api/referral/validate/${encodeURIComponent(code)}`);
			if (res.ok) {
				const data = await res.json();
				if (data.valid !== false) {
					if (data.referrerName) {
						pending.referrerName = data.referrerName;
						try {
							localStorage.setItem(STORAGE_KEY, JSON.stringify(pending));
						} catch {}
					}
				} else {
					clearPendingReferral();
					if (isDeepLinkPath) try {
						window.history.replaceState({}, "", "/");
					} catch {}
					return null;
				}
			}
		} catch {}
		if (isDeepLinkPath) try {
			window.history.replaceState({}, "", "/");
		} catch {}
		return pending;
	}
	const existing = getPendingReferral();
	if (existing?.code && isSelfReferralCode(existing.code)) {
		clearPendingReferral();
		return null;
	}
	if (existing?.code && !existing.referrerName) try {
		const res = await apiFetch(`/api/referral/validate/${encodeURIComponent(existing.code)}`);
		if (res.ok) {
			const data = await res.json();
			if (data.valid && data.referrerName) {
				existing.referrerName = data.referrerName;
				try {
					localStorage.setItem(STORAGE_KEY, JSON.stringify(existing));
				} catch {}
			}
		}
	} catch {}
	return existing;
}
/**
* Retrieves the currently pending referral code from localStorage or cookie.
*/
function getPendingReferral() {
	if (typeof window === "undefined") return null;
	try {
		const raw = localStorage.getItem(STORAGE_KEY);
		if (raw) {
			const parsed = JSON.parse(raw);
			if (parsed?.code) {
				if (isSelfReferralCode(parsed.code)) {
					clearPendingReferral();
					return null;
				}
				return parsed;
			}
		}
		const directRef = localStorage.getItem("ref");
		if (directRef && directRef.trim()) {
			if (isSelfReferralCode(directRef.trim())) {
				clearPendingReferral();
				return null;
			}
			return {
				code: directRef.trim(),
				capturedAt: Date.now()
			};
		}
	} catch {}
	const cookieCode = getCookie(COOKIE_NAME);
	if (cookieCode) {
		if (isSelfReferralCode(cookieCode)) {
			clearPendingReferral();
			return null;
		}
		return {
			code: cookieCode,
			capturedAt: Date.now()
		};
	}
	return null;
}
/**
* Clears pending referral data once attributed or rejected.
*/
function clearPendingReferral() {
	if (typeof window === "undefined") return;
	try {
		localStorage.removeItem(STORAGE_KEY);
		localStorage.removeItem("ref");
	} catch {}
	clearCookie(COOKIE_NAME);
}
/**
* Claims a pending referral code for the newly authenticated user.
* Idempotent: safe to call on every auth state change.
*/
async function claimPendingReferralAfterAuth(userId, _email) {
	const pending = getPendingReferral();
	if (!pending || !pending.code) return {
		success: false,
		error: "No pending referral code found"
	};
	if (isSelfReferralCode(pending.code) || pending.code.toLowerCase() === computeCanonicalReferralCode(userId).toLowerCase()) {
		clearPendingReferral();
		return {
			success: false,
			error: "Self-referrals are not permitted"
		};
	}
	try {
		const token = await auth.currentUser?.getIdToken().catch(() => null);
		const headers = {
			"Content-Type": "application/json",
			"X-Kinich-Client-Id": userId || auth.currentUser?.uid || getOrCreateSharedClientId()
		};
		if (token) headers["Authorization"] = `Bearer ${token}`;
		const creationTime = auth.currentUser?.metadata?.creationTime;
		const accountCreatedAtMs = creationTime ? new Date(creationTime).getTime() : Date.now();
		const res = await apiFetch("/api/referral/claim", {
			method: "POST",
			headers,
			body: JSON.stringify({
				code: pending.code,
				accountCreatedAtMs
			})
		});
		const data = await res.json().catch(() => ({}));
		if (res.ok && data.success) {
			clearPendingReferral();
			return {
				success: true,
				alreadyClaimed: Boolean(data.alreadyClaimed)
			};
		}
		if (res.status === 400 || res.status === 409) clearPendingReferral();
		return {
			success: false,
			error: data.error || data.message || `Referral claim failed with status ${res.status}`
		};
	} catch (err) {
		return {
			success: false,
			error: err?.message || "Network error while claiming referral"
		};
	}
}
/**
* Fetches the user's live referral dashboard from the backend.
*/
async function fetchUserReferralDashboard() {
	try {
		const token = await auth.currentUser?.getIdToken().catch(() => null);
		const headers = { "X-Kinich-Client-Id": auth.currentUser?.uid || getOrCreateSharedClientId() };
		if (token) headers["Authorization"] = `Bearer ${token}`;
		const res = await apiFetch("/api/referral/me", { headers });
		if (res.ok) return await res.json();
	} catch {}
	return null;
}
